begin;
alter table public.profiles enable row level security;
alter table public.account_settings enable row level security;
alter table public.follows enable row level security;
alter table public.friendships enable row level security;
alter table public.blocks enable row level security;
alter table public.mutes enable row level security;
alter table public.media_assets enable row level security;
alter table public.posts enable row level security;
alter table public.post_media enable row level security;
alter table public.post_likes enable row level security;
alter table public.comments enable row level security;
alter table public.reposts enable row level security;
alter table public.collections enable row level security;
alter table public.collection_posts enable row level security;
alter table public.recommendation_feedback enable row level security;
alter table public.live_sessions enable row level security;
alter table public.live_participants enable row level security;
alter table public.live_guest_requests enable row level security;
alter table public.live_chat_messages enable row level security;
alter table public.live_polls enable row level security;
alter table public.live_poll_votes enable row level security;
alter table public.conversations enable row level security;
alter table public.conversation_members enable row level security;
alter table public.messages enable row level security;
alter table public.message_receipts enable row level security;
alter table public.notifications enable row level security;
alter table public.reports enable row level security;
alter table public.moderation_actions enable row level security;
alter table public.appeals enable row level security;
alter table public.background_jobs enable row level security;
alter table public.event_outbox enable row level security;
alter table public.wallets enable row level security;
alter table public.coin_packages enable row level security;
alter table public.gifts enable row level security;
alter table public.gift_transactions enable row level security;
alter table public.ledger_entries enable row level security;
alter table public.creator_earnings enable row level security;
alter table public.gifter_level_rules enable row level security;
alter table public.gifter_profiles enable row level security;
alter table public.leaderboard_periods enable row level security;
alter table public.leaderboard_scores enable row level security;
alter table public.payment_orders enable row level security;
alter table public.payment_events enable row level security;
alter table public.payout_requests enable row level security;
alter table public.financial_audit_log enable row level security;
alter table public.application_settings enable row level security;
alter table public.scheduled_tasks enable row level security;
alter table public.creator_analytics_daily enable row level security;

create policy profiles_public_read on public.profiles for select using (deleted_at is null and (visibility='public' or id=auth.uid()));
create policy profiles_self_insert on public.profiles for insert with check (id=auth.uid());
create policy profiles_self_update on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy account_settings_self on public.account_settings for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy follows_read on public.follows for select using (true);
create policy follows_self_write on public.follows for all using(follower_id=auth.uid()) with check(follower_id=auth.uid());
create policy friendships_party_read on public.friendships for select using(requester_id=auth.uid() or addressee_id=auth.uid());
create policy friendships_party_write on public.friendships for insert with check(requester_id=auth.uid());
create policy friendships_party_update on public.friendships for update using(requester_id=auth.uid() or addressee_id=auth.uid()) with check(requester_id=auth.uid() or addressee_id=auth.uid());
create policy blocks_self on public.blocks for all using(blocker_id=auth.uid()) with check(blocker_id=auth.uid());
create policy mutes_self on public.mutes for all using(muter_id=auth.uid()) with check(muter_id=auth.uid());
create policy media_owner_read on public.media_assets for select using(owner_id=auth.uid() or exists(select 1 from public.post_media pm join public.posts p on p.id=pm.post_id where pm.media_id=id and p.visibility='public' and p.status='published'));
create policy media_owner_insert on public.media_assets for insert with check(owner_id=auth.uid());
create policy media_owner_update on public.media_assets for update using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy posts_read on public.posts for select using(deleted_at is null and status='published' and (visibility='public' or author_id=auth.uid() or (visibility='followers' and exists(select 1 from public.follows f where f.follower_id=auth.uid() and f.followed_id=author_id))));
create policy posts_self_insert on public.posts for insert with check(author_id=auth.uid());
create policy posts_self_update on public.posts for update using(author_id=auth.uid()) with check(author_id=auth.uid());
create policy post_media_read on public.post_media for select using(exists(select 1 from public.posts p where p.id=post_id and p.status='published' and (p.visibility='public' or p.author_id=auth.uid())));
create policy post_media_author_insert on public.post_media for insert with check(exists(select 1 from public.posts p where p.id=post_id and p.author_id=auth.uid()));
create policy post_likes_read on public.post_likes for select using(exists(select 1 from public.posts p where p.id=post_id and p.status='published' and p.visibility='public') or user_id=auth.uid());
create policy post_likes_self on public.post_likes for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy comments_read on public.comments for select using(status='visible' and exists(select 1 from public.posts p where p.id=post_id and p.status='published' and (p.visibility='public' or p.author_id=auth.uid())));
create policy comments_self_insert on public.comments for insert with check(author_id=auth.uid() and exists(select 1 from public.posts p where p.id=post_id and p.comments_enabled and p.status='published'));
create policy comments_self_update on public.comments for update using(author_id=auth.uid()) with check(author_id=auth.uid());
create policy reposts_read on public.reposts for select using(user_id=auth.uid() or exists(select 1 from public.profiles p where p.id=user_id and p.visibility='public'));
create policy reposts_self on public.reposts for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy collections_self on public.collections for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy collection_posts_self on public.collection_posts for all using(exists(select 1 from public.collections c where c.id=collection_id and c.owner_id=auth.uid())) with check(exists(select 1 from public.collections c where c.id=collection_id and c.owner_id=auth.uid()));
create policy recommendation_feedback_self on public.recommendation_feedback for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy live_sessions_read on public.live_sessions for select using((visibility='public' and status in ('scheduled','live')) or host_id=auth.uid() or public.is_live_participant(id,auth.uid()));
create policy live_sessions_host_create on public.live_sessions for insert with check(host_id=auth.uid());
create policy live_sessions_host_update on public.live_sessions for update using(host_id=auth.uid()) with check(host_id=auth.uid());
create policy live_participants_read on public.live_participants for select using(user_id=auth.uid() or public.is_live_host(live_session_id,auth.uid()));
create policy live_participants_self_request on public.live_participants for insert with check(user_id=auth.uid() and role='viewer' and can_publish_audio=false and can_publish_video=false);
create policy live_guest_request_party_read on public.live_guest_requests for select using(requester_id=auth.uid() or exists(select 1 from public.live_sessions ls where ls.id=live_session_id and ls.host_id=auth.uid()));
create policy live_guest_request_self on public.live_guest_requests for insert with check(requester_id=auth.uid());
create policy live_chat_read on public.live_chat_messages for select using(status='visible' and exists(select 1 from public.live_sessions ls where ls.id=live_session_id and (ls.visibility='public' or ls.host_id=auth.uid() or exists(select 1 from public.live_participants lp where lp.live_session_id=ls.id and lp.user_id=auth.uid() and lp.status='joined'))));
create policy live_chat_insert on public.live_chat_messages for insert with check(sender_id=auth.uid() and exists(select 1 from public.live_sessions ls where ls.id=live_session_id and ls.status='live') and not exists(select 1 from public.blocks b where (b.blocker_id=auth.uid() and b.blocked_id=(select host_id from public.live_sessions where id=live_session_id)) or (b.blocked_id=auth.uid() and b.blocker_id=(select host_id from public.live_sessions where id=live_session_id))));
create policy live_polls_read on public.live_polls for select using(exists(select 1 from public.live_sessions ls where ls.id=live_session_id and ls.visibility='public') or created_by=auth.uid());
create policy live_polls_host_insert on public.live_polls for insert with check(created_by=auth.uid() and exists(select 1 from public.live_sessions ls where ls.id=live_session_id and ls.host_id=auth.uid()));
create policy live_poll_votes_self on public.live_poll_votes for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy conversations_member_read on public.conversations for select using(public.is_conversation_member(id,auth.uid()));
create policy conversation_members_self_read on public.conversation_members for select using(user_id=auth.uid() or public.is_conversation_admin(conversation_id,auth.uid()));
create policy conversation_members_create on public.conversation_members for insert with check(user_id=auth.uid());
create policy messages_member_read on public.messages for select using(public.is_conversation_member(conversation_id,auth.uid()));
create policy messages_member_insert on public.messages for insert with check(sender_id=auth.uid() and public.is_conversation_member(conversation_id,auth.uid()) and not exists(select 1 from public.blocks b where (b.blocker_id=auth.uid() and b.blocked_id in(select user_id from public.conversation_members where conversation_id=messages.conversation_id)) or (b.blocked_id=auth.uid() and b.blocker_id in(select user_id from public.conversation_members where conversation_id=messages.conversation_id))));
create policy message_receipts_self on public.message_receipts for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy notifications_self on public.notifications for select using(recipient_id=auth.uid());
create policy notifications_self_update on public.notifications for update using(recipient_id=auth.uid()) with check(recipient_id=auth.uid());
create policy reports_self_insert on public.reports for insert with check(reporter_id=auth.uid());
create policy reports_party_read on public.reports for select using(reporter_id=auth.uid());
create policy appeals_self on public.appeals for all using(appellant_id=auth.uid()) with check(appellant_id=auth.uid());
create policy coin_packages_public on public.coin_packages for select using(is_active=true);
create policy gifts_public_read on public.gifts for select using(active=true);
create policy wallets_self_read on public.wallets for select using(user_id=auth.uid());
create policy payment_orders_self_read on public.payment_orders for select using(user_id=auth.uid());
create policy payment_orders_self_insert on public.payment_orders for insert with check(user_id=auth.uid() and status='created');
create policy creator_earnings_self_read on public.creator_earnings for select using(creator_id=auth.uid());
create policy payout_requests_self_read on public.payout_requests for select using(creator_id=auth.uid());
create policy ledger_self_read on public.ledger_entries for select using(user_id=auth.uid());
create policy gift_transactions_public_live_read on public.gift_transactions for select using(sender_id=auth.uid() or creator_id=auth.uid() or exists(select 1 from public.live_sessions ls where ls.id=live_session_id and ls.visibility='public' and ls.status='live'));
create policy gifter_profiles_public_read on public.gifter_profiles for select using(true);
create policy gifter_profiles_self_insert on public.gifter_profiles for insert with check(user_id=auth.uid());
create policy gifter_level_rules_public on public.gifter_level_rules for select using(active=true);
create policy leaderboard_periods_public on public.leaderboard_periods for select using(true);
create policy leaderboard_scores_public on public.leaderboard_scores for select using(true);
create policy application_settings_public_selected on public.application_settings for select using(key in ('gift_revenue_share','gifter_levels','monthly_leaderboard_reset'));
create policy creator_analytics_self_read on public.creator_analytics_daily for select using(creator_id=auth.uid());

-- Operational, reconciliation, moderation, and provider tables are server-only through service_role.
revoke all on public.background_jobs,public.event_outbox,public.payment_events,public.financial_audit_log,public.moderation_actions,public.scheduled_tasks from anon,authenticated;
revoke insert,update,delete on public.ledger_entries from anon,authenticated;
revoke insert,update,delete on public.gift_transactions from anon,authenticated;
revoke insert,update,delete on public.creator_earnings from anon,authenticated;
revoke insert,update,delete on public.gifter_level_rules from anon,authenticated;
revoke insert,update,delete on public.application_settings from anon,authenticated;
revoke insert,update,delete on public.coin_packages from anon,authenticated;
revoke insert,update,delete on public.gifts from anon,authenticated;
revoke insert,update,delete on public.leaderboard_scores from anon,authenticated;
grant execute on function public.finalize_paypal_webhook(text,text,bigint,text,text) to service_role;
grant execute on function public.update_payout_provider_status(uuid,text,text,text) to service_role;
grant execute on function public.claim_background_jobs(text,integer) to service_role;
grant execute on function public.finish_background_job(uuid,boolean,text) to service_role;
grant execute on function public.publish_outbox_event(uuid) to service_role;
grant execute on function public.send_gift_transaction(uuid,text,text) to authenticated;
grant execute on function public.finalize_coin_purchase(text,text,bigint) to authenticated;
grant execute on function public.request_creator_payout(bigint,text) to authenticated;
commit;
